// Package billing computes invoices.
package billing

import (
	"fmt"
	"time"

	"example.com/app/internal/clock"
	"example.com/app/internal/log"
)

// Line is one line of an invoice.
type Line struct {
	SKU       string `json:"sku"`
	Quantity  int    `json:"quantity"`
	UnitCents int64  `json:"unit_cents"`
}

// Invoice is a computed invoice. TotalCents is the sum of the lines before
// discount and tax. GrandTotalCents is TotalCents - DiscountCents + TaxCents.
type Invoice struct {
	ID              string    `json:"id"`
	Customer        string    `json:"customer"`
	Region          string    `json:"region"`
	Lines           []Line    `json:"lines"`
	TotalCents      int64     `json:"total_cents"`
	DiscountCode    string    `json:"discount_code"`
	DiscountCents   int64     `json:"discount_cents"`
	TaxCents        int64     `json:"tax_cents"`
	GrandTotalCents int64     `json:"grand_total_cents"`
	IssuedAt        time.Time `json:"issued_at"`
}

// Options holds the optional inputs to Price.
type Options struct {
	// Clock gives the issue time and is checked against code expiry.
	// It defaults to the system clock.
	Clock clock.Clock
	// Region is the tax region, for example "FR" or "US-CA".
	Region string
	// Taxes holds rates by region. When nil, no tax is charged.
	Taxes TaxTable
	// Code is the discount code to apply, if any.
	Code *DiscountCode
	// Redemptions enforces one use per customer. When nil, reuse is not checked.
	Redemptions Redemptions
}

// Price builds an invoice for a customer: lines, then at most one discount,
// then tax on the discounted total.
func Price(id, customer string, lines []Line, opts Options) (Invoice, error) {
	if customer == "" {
		return Invoice{}, ErrNoCustomer
	}
	clk := opts.Clock
	if clk == nil {
		clk = clock.Real{}
	}
	now := clk.Now()

	var total int64
	for _, l := range lines {
		total += int64(l.Quantity) * l.UnitCents
	}
	inv := Invoice{
		ID: id, Customer: customer, Region: opts.Region, Lines: lines,
		TotalCents: total, IssuedAt: now,
	}

	if c := opts.Code; c != nil {
		if err := c.validate(); err != nil {
			return Invoice{}, err
		}
		if !c.ExpiresAt.IsZero() && !now.Before(c.ExpiresAt) {
			return Invoice{}, fmt.Errorf("code %q expired at %s: %w", c.Code, c.ExpiresAt.Format(time.RFC3339), ErrCodeExpired)
		}
		inv.DiscountCents = c.amount(total)
		inv.DiscountCode = c.Code
	}

	afterDiscount := total - inv.DiscountCents
	if opts.Taxes != nil {
		tax, err := opts.Taxes.tax(opts.Region, afterDiscount)
		if err != nil {
			return Invoice{}, err
		}
		inv.TaxCents = tax
	}
	// Redeem last, after every check that can fail, so a rejected invoice
	// does not consume the code.
	if inv.DiscountCode != "" && opts.Redemptions != nil && !opts.Redemptions.Redeem(customer, inv.DiscountCode) {
		return Invoice{}, fmt.Errorf("code %q for customer %q: %w", inv.DiscountCode, customer, ErrCodeUsed)
	}
	inv.GrandTotalCents = afterDiscount + inv.TaxCents
	return inv, nil
}

// Compute builds an invoice for a customer without discount or tax. With no
// customer it logs an error and returns the zero Invoice.
func Compute(id, customer string, lines []Line) Invoice {
	inv, err := Price(id, customer, lines, Options{})
	if err != nil {
		log.Error("compute invoice", "id", id, "err", err)
		return Invoice{}
	}
	log.Info("computed invoice", "id", id, "customer", customer, "total_cents", inv.TotalCents)
	return inv
}

// Describe returns a one-line summary of an invoice.
func Describe(inv Invoice) string {
	return fmt.Sprintf("%s %s %d.%02d", inv.ID, inv.Customer, inv.TotalCents/100, inv.TotalCents%100)
}

// Meta holds free-form invoice metadata.
type Meta map[string]any

